PRAGMA foreign_keys=ON;
CREATE TABLE people(id TEXT PRIMARY KEY, owner TEXT NOT NULL, preferredLocale TEXT NOT NULL, countryCode TEXT NOT NULL, timeZone TEXT NOT NULL, consents TEXT NOT NULL, heartbeat TEXT, heartbeatMinutes INTEGER NOT NULL DEFAULT 120, createdAt TEXT NOT NULL);
CREATE TABLE grants(personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, uid TEXT NOT NULL, scopes TEXT NOT NULL, preferredLocale TEXT NOT NULL, preferences TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(personId,uid));
CREATE TABLE invites(hash TEXT PRIMARY KEY,personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,scopes TEXT NOT NULL,expiresAt TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE plans(id TEXT PRIMARY KEY,personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,version INTEGER NOT NULL,data TEXT NOT NULL,updatedAt TEXT NOT NULL);
CREATE TABLE events(id TEXT PRIMARY KEY,personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,type TEXT NOT NULL,occurredAt TEXT NOT NULL,receivedAt TEXT NOT NULL,payload TEXT NOT NULL,actor TEXT NOT NULL);
CREATE INDEX events_person_time ON events(personId,receivedAt);
CREATE TABLE subscriptions(uid TEXT NOT NULL,token TEXT NOT NULL,preferredLocale TEXT NOT NULL,PRIMARY KEY(uid,token));
CREATE TABLE alerts(id TEXT PRIMARY KEY,personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,uid TEXT NOT NULL,kind TEXT NOT NULL,occurredAt TEXT NOT NULL,data TEXT NOT NULL,delivery TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,nextAttempt TEXT NOT NULL);
CREATE INDEX alerts_delivery ON alerts(delivery,nextAttempt);
CREATE TABLE audit(id TEXT PRIMARY KEY,personId TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,actor TEXT NOT NULL,action TEXT NOT NULL,at TEXT NOT NULL,version INTEGER);
CREATE TABLE limits(uid TEXT NOT NULL,bucket INTEGER NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(uid,bucket));
